 else{$l=q("SELECT * FROM leases WHERE room_id=? AND status='active' ORDER BY id DESC LIMIT 1",[$rm['id']])->fetch();if($l)echo leasedoc($l+['room_no'=>$rm['room_no'],'type'=>$rm['type'],'name'=>$rm['name'],'phone'=>$rm['phone']]);?>
