<script>function addm(n){var s=document.getElementById('ls').value;if(!s)return;var d=new Date(s+'T00:00:00');d.setMonth(d.getMonth()+n);var p=function(x){return String(x).padStart(2,'0')};document.getElementById('le').value=d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())}</script>
<?php }}
